import numpy as np

GRAPH = {
    "S": (("A", 4.0), ("B", 1.0), ("C", 2.0)),
    "A": (("G", 3.0),),
    "B": (("A", 1.0), ("G", 8.0)),
    "C": (("D", 2.0),),
    "D": (("G", 5.0),),
    "G": (),
    "X": (),
}
H = {"S": 4.0, "A": 3.0, "B": 3.0, "C": 5.0,
     "D": 5.0, "G": 0.0, "X": 0.0}

# Positions are joint1/joint2 angles, not Cartesian tool positions.
ROADMAP_POSITIONS = {
    "S": np.array([-0.60, -0.80]),
    "L": np.array([-0.30, -1.00]),
    "M": np.array([0.00, -1.00]),
    "R": np.array([0.30, -1.00]),
    "G": np.array([0.60, -0.80]),
    "U": np.array([0.00, -0.45]),
}
ROADMAP_LINKS = (("S", "G"), ("S", "L"), ("L", "M"), ("M", "R"),
                 ("R", "G"), ("S", "U"), ("U", "G"))


def make_roadmap():
    graph = {name: [] for name in ROADMAP_POSITIONS}
    for left, right in ROADMAP_LINKS:
        cost = float(np.linalg.norm(ROADMAP_POSITIONS[left] -
                                    ROADMAP_POSITIONS[right]))
        graph[left].append((right, cost))
        graph[right].append((left, cost))
    return {name: tuple(edges) for name, edges in graph.items()}

